const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

const job = $input.first().json;

if (!job.job_exists) {
  throw new Error(`Job ${job.requested_job_id} was not found`);
}

const requiredScenesByDuration = { 15: 4, 30: 8, 45: 12, 60: 15 };
const targetDuration = Number(job.target_duration_seconds);
const requiredSceneCount = requiredScenesByDuration[targetDuration];

if (!requiredSceneCount) {
  throw new Error(`Unsupported target_duration_seconds: ${job.target_duration_seconds}`);
}

const finalVideoPath = typeof job.final_video_path === 'string'
  ? job.final_video_path.trim()
  : '';

const alreadyComplete =
  job.status === 'review_ready' &&
  job.current_stage === 'review' &&
  finalVideoPath !== '';

const normalRenderState =
  job.status === 'processing' &&
  ['visuals', 'render'].includes(job.current_stage);

const retryRenderState =
  job.status === 'failed' &&
  job.current_stage === 'render';

if (!alreadyComplete && !normalRenderState && !retryRenderState) {
  throw new Error(
    `Job ${job.job_id} is not eligible for render: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

if (finalVideoPath && !alreadyComplete) {
  throw new Error(
    `Job ${job.job_id} has final_video_path in an inconsistent state: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

if (!Array.isArray(job.scenes)) {
  throw new Error(`Job ${job.job_id} scenes are unavailable`);
}

if (
  Number(job.scene_count) !== requiredSceneCount ||
  job.scenes.length !== requiredSceneCount
) {
  throw new Error(
    `Job ${job.job_id} must have exactly ${requiredSceneCount} scenes`
  );
}

let totalAudioDuration = 0;
const normalizedScenes = [];

for (let index = 0; index < job.scenes.length; index += 1) {
  const scene = job.scenes[index];
  const expectedSceneNumber = index + 1;

  if (Number(scene.scene_number) !== expectedSceneNumber) {
    throw new Error(
      `Invalid scene_number at position ${expectedSceneNumber}: received ${scene.scene_number}`
    );
  }

  const narration = String(scene.narration ?? '').replace(/\s+/gu, ' ').trim();
  const audioPath = String(scene.audio_path ?? '').trim();
  const visualPath = String(scene.visual_path ?? '').trim();
  const duration = Number(scene.duration_seconds);

  if (!narration) throw new Error(`Scene ${expectedSceneNumber} narration is missing`);
  if (!audioPath) throw new Error(`Scene ${expectedSceneNumber} audio_path is missing`);
  if (!visualPath) throw new Error(`Scene ${expectedSceneNumber} visual_path is missing`);
  if (!Number.isFinite(duration) || duration <= 0) {
    throw new Error(`Scene ${expectedSceneNumber} duration_seconds is invalid`);
  }

  totalAudioDuration += duration;
  normalizedScenes.push({
    scene_number: expectedSceneNumber,
    narration,
    audio_path: audioPath,
    visual_path: visualPath,
    duration_seconds: duration,
  });
}

const minDuration = targetDuration * 0.9;
const maxDuration = targetDuration * 1.1;

if (totalAudioDuration < minDuration - 0.001 || totalAudioDuration > maxDuration + 0.001) {
  throw new Error(
    `Voiceover duration ${totalAudioDuration.toFixed(3)}s is outside the allowed ` +
    `${minDuration.toFixed(3)}-${maxDuration.toFixed(3)}s render window for target ${targetDuration}s`
  );
}

const expectedPath = `jobs/${job.job_id}/render/final.mp4`;
if (alreadyComplete && finalVideoPath !== expectedPath) {
  throw new Error(
    `Completed job ${job.job_id} has unexpected final_video_path: ${finalVideoPath}`
  );
}

return [{
  json: {
    ...job,
    scenes: normalizedScenes,
    required_scene_count: requiredSceneCount,
    total_audio_duration_seconds: Number(totalAudioDuration.toFixed(6)),
    min_audio_duration_seconds: Number(minDuration.toFixed(6)),
    max_audio_duration_seconds: Number(maxDuration.toFixed(6)),
    expected_final_video_path: expectedPath,
    already_complete: alreadyComplete,
  },
}];

return [{
  json: {
    job_id: $json.job_id,
    status: $json.status,
    current_stage: $json.current_stage,
    final_video_path: $json.final_video_path,
    render_complete: true,
    already_complete: true,
  },
}];

if ($json.ready_to_run !== true || $json.status !== 'processing' || $json.current_stage !== 'render') {
  throw new Error(
    `Render stage could not start for job ${$json.job_id}: ` +
    `ready=${$json.ready_to_run}, status=${$json.status}, current_stage=${$json.current_stage}`
  );
}
return [{ json: { job_id: $json.job_id } }];

const job = $('Require Eligible Render Job').first().json;
return [{
  json: {
    job_id: job.job_id,
    scenes: job.scenes.map((scene) => ({
      scene_number: scene.scene_number,
      narration: scene.narration,
      audio_path: scene.audio_path,
      visual_path: scene.visual_path,
      duration_seconds: scene.duration_seconds,
    })),
  },
}];

const result = $input.first().json;
const job = $('Require Eligible Render Job').first().json;
const expectedPath = job.expected_final_video_path;

function requireValue(condition, message) {
  if (!condition) throw new Error(message);
}

requireValue(result.video_path === expectedPath, `Unexpected render video_path: ${result.video_path}`);
requireValue(result.media_type === 'video', `Unexpected media_type: ${result.media_type}`);
requireValue(Number(result.width) === 1080, `Unexpected render width: ${result.width}`);
requireValue(Number(result.height) === 1920, `Unexpected render height: ${result.height}`);
requireValue(String(result.video_codec ?? '').toLowerCase() === 'h264', `Unexpected video codec: ${result.video_codec}`);
requireValue(String(result.video_pix_fmt ?? '').toLowerCase() === 'yuv420p', `Unexpected pixel format: ${result.video_pix_fmt}`);
requireValue(String(result.audio_codec ?? '').toLowerCase() === 'aac', `Unexpected audio codec: ${result.audio_codec}`);
requireValue(Number(result.audio_sample_rate) === 48000, `Unexpected audio sample rate: ${result.audio_sample_rate}`);
requireValue(Number(result.audio_channels) === 2, `Unexpected audio channel count: ${result.audio_channels}`);
requireValue(result.subtitles_burned_in === true, 'Render did not confirm burned subtitles');
requireValue(Number.isFinite(Number(result.bytes)) && Number(result.bytes) > 0, `Invalid rendered byte size: ${result.bytes}`);

const renderedDuration = Number(result.duration_seconds);
const expectedAudioDuration = Number(job.total_audio_duration_seconds);
const workerExpectedAudioDuration = Number(result.expected_audio_duration_seconds);
requireValue(Number.isFinite(renderedDuration) && renderedDuration > 0, `Invalid rendered duration: ${result.duration_seconds}`);
requireValue(Number.isFinite(workerExpectedAudioDuration), 'media-worker expected audio duration is missing');
requireValue(Math.abs(workerExpectedAudioDuration - expectedAudioDuration) <= 0.15,
  `media-worker audio total ${workerExpectedAudioDuration} differs from persisted total ${expectedAudioDuration}`);
requireValue(Math.abs(renderedDuration - expectedAudioDuration) <= 0.6,
  `Rendered duration ${renderedDuration} differs from audio total ${expectedAudioDuration}`);

requireValue(Array.isArray(result.scene_timings), 'scene_timings are missing');
requireValue(result.scene_timings.length === job.scenes.length,
  `scene_timings count ${result.scene_timings.length} differs from scene count ${job.scenes.length}`);

let previousEnd = 0;
for (let index = 0; index < result.scene_timings.length; index += 1) {
  const timing = result.scene_timings[index];
  const scene = job.scenes[index];
  const expectedSceneNumber = index + 1;
  const start = Number(timing.start_seconds);
  const end = Number(timing.end_seconds);
  const duration = Number(timing.duration_seconds);
  requireValue(Number(timing.scene_number) === expectedSceneNumber,
    `Invalid timing scene_number at index ${expectedSceneNumber}`);
  requireValue(Number.isFinite(start) && Number.isFinite(end) && Number.isFinite(duration),
    `Invalid scene timing values at scene ${expectedSceneNumber}`);
  requireValue(Math.abs(start - previousEnd) <= 0.15,
    `Scene ${expectedSceneNumber} timing is not contiguous`);
  requireValue(Math.abs(duration - Number(scene.duration_seconds)) <= 0.15,
    `Scene ${expectedSceneNumber} render duration differs from persisted audio duration`);
  requireValue(Math.abs((end - start) - duration) <= 0.15,
    `Scene ${expectedSceneNumber} timing interval is inconsistent`);
  previousEnd = end;
}

requireValue(Math.abs(previousEnd - expectedAudioDuration) <= 0.15,
  `Final scene end ${previousEnd} differs from audio total ${expectedAudioDuration}`);

return [{
  json: {
    job_id: job.job_id,
    final_video_path: expectedPath,
    render_duration_seconds: renderedDuration,
    expected_audio_duration_seconds: expectedAudioDuration,
    rendered_bytes: Number(result.bytes),
    width: Number(result.width),
    height: Number(result.height),
    video_codec: String(result.video_codec),
    audio_codec: String(result.audio_codec),
    subtitles_burned_in: true,
    scene_count: job.scenes.length,
  },
}];

if ($json.persisted !== true) {
  throw new Error(`Render result was not persisted for job ${$json.job_id}`);
}
if ($json.status !== 'review_ready' || $json.current_stage !== 'review') {
  throw new Error(
    `Unexpected job state after render: status=${$json.status}, current_stage=${$json.current_stage}`
  );
}
const expectedPath = $('Require Eligible Render Job').first().json.expected_final_video_path;
if ($json.final_video_path !== expectedPath) {
  throw new Error(`Unexpected persisted final_video_path: ${$json.final_video_path}`);
}
return [{
  json: {
    job_id: $json.job_id,
    status: $json.status,
    current_stage: $json.current_stage,
    final_video_path: $json.final_video_path,
    render_complete: true,
    already_complete: !$json.transitioned,
  },
}];

const errorItem = $input.first()?.json ?? {};
const job = $('Require Eligible Render Job').first().json;
if (typeof job.job_id !== 'string' || job.job_id.trim() === '') {
  throw new Error('Validated job_id is unavailable while recording render failure');
}
const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.errorDescription,
  errorItem.message,
];
let message = candidates.find((value) => typeof value === 'string' && value.trim() !== '');
if (!message) {
  try { message = JSON.stringify(errorItem); } catch { message = ''; }
}
message = String(message || 'Unknown video render stage failure').trim().slice(0, 4000);
return [{ json: { job_id: job.job_id, last_error: message } }];
